sys_script_include.script:
var ReviewableMediaUtils = Class.create();
ReviewableMediaUtils.prototype = {
    initialize: function() {
    },
	getQualifier: function(){
		var reviewedMediaIds = this._getReviewedMediaIds();
		if(reviewedMediaIds.length === 0){
			return "active=true";
		}
		return "active=true^sys_idNOT IN" + reviewedMediaIds.join(",");
	},

	_getReviewedMediaIds:function(){
		var mediaIds = [];
		var grReview = new GlideRecord("x_1974937_nowflix_review");
		grReview.addQuery("sys_created_by", gs.getUserName());
		grReview.addQuery("state","!=", "reject");
		grReview.addNotNullQuery("media");
		grReview.query();
		while(grReview.next()){
			mediaIds.push(grReview.getValue("media"));
		}
		return mediaIds;
	},

    type: 'ReviewableMediaUtils'
};
